"""
Screen 2 — NIC selection for sys-net VFIO passthrough.
"""

import gi
gi.require_version("Gtk", "4.0")
gi.require_version("Adw", "1")

from gi.repository import Gtk, Adw

from .base import BasePage
from ..state import WizardState, NICDevice
from typing import Callable


class NICScreen(BasePage):
    def __init__(self, state: WizardState, go_to: Callable):
        super().__init__(state, go_to, title="Network Interfaces", tag="nics")

    def _build(self):
        self._body.append(
            self.make_page_header(
                "Select NICs for sys-net",
                "Choose which physical network interfaces to pass through to "
                "sys-net. At least one is required. The host will no longer "
                "have direct network access after reboot.",
            )
        )

        # Use a plain Adw.PreferencesGroup as a labelled container,
        # but put a Gtk.ListBox inside it for the dynamic rows.
        # ListBox.remove() is reliable; PreferencesGroup.remove() is not.
        nic_group_wrapper = Adw.PreferencesGroup()
        nic_group_wrapper.set_title("Available network interfaces")
        self._body.append(nic_group_wrapper)

        self._nic_list = Gtk.ListBox()
        self._nic_list.set_selection_mode(Gtk.SelectionMode.NONE)
        self._nic_list.add_css_class("boxed-list")
        nic_group_wrapper.add(self._nic_list)

        self._no_nics_label = Gtk.Label(
            label="No passthrough-capable NICs detected. "
                  "Return to the previous screen."
        )
        self._no_nics_label.add_css_class("dim-label")
        self._no_nics_label.set_visible(False)
        self._body.append(self._no_nics_label)

        self._warn_banner = Adw.Banner()
        self._warn_banner.set_title(
            "One or more NICs share an IOMMU group with other devices. "
            "Passing these through may also expose those devices to sys-net."
        )
        self._warn_banner.set_revealed(False)
        self._body.append(self._warn_banner)

        self._btn_row = self.make_button_row(
            back_label="Back",
            back_cb=lambda: self.go_to("back"),
            next_label="Continue",
            next_cb=self._on_continue,
        )
        self._body.append(self._btn_row)
        self._next_btn = self._btn_row.get_last_child()
        self._next_btn.set_sensitive(False)

        self._check_buttons: dict[str, Gtk.CheckButton] = {}
        self._nic_rows: list[Gtk.ListBoxRow] = []

    def on_enter(self):
        """Rebuild the NIC list each time this screen is shown."""
        # Remove previously added rows cleanly via ListBox.remove()
        for row in self._nic_rows:
            self._nic_list.remove(row)
        self._nic_rows.clear()
        self._check_buttons.clear()

        if not self.state.nics:
            self._no_nics_label.set_visible(True)
            return

        contaminated = False
        for nic in self.state.nics:
            row = self._make_nic_row(nic)
            self._nic_list.append(row)
            self._nic_rows.append(row)
            if not nic.group_isolated:
                contaminated = True

        self._warn_banner.set_revealed(contaminated)
        self._update_continue()

    def _make_nic_row(self, nic: NICDevice) -> Gtk.ListBoxRow:
        row = Gtk.ListBoxRow()
        row.set_activatable(False)
        row.set_selectable(False)

        inner = Gtk.Box(orientation=Gtk.Orientation.HORIZONTAL, spacing=12)
        inner.set_margin_top(10)
        inner.set_margin_bottom(10)
        inner.set_margin_start(12)
        inner.set_margin_end(12)

        check = Gtk.CheckButton()
        check.set_active(nic in self.state.selected_nics or nic.group_isolated)
        check.set_valign(Gtk.Align.CENTER)
        check.connect("toggled", self._on_toggled, nic)
        inner.append(check)

        text = Gtk.Box(orientation=Gtk.Orientation.VERTICAL, spacing=2)
        text.set_hexpand(True)

        title_lbl = Gtk.Label(label=nic.iface)
        title_lbl.set_xalign(0)
        title_lbl.add_css_class("heading")
        text.append(title_lbl)

        group_status = "Isolated group" if nic.group_isolated else "Shared group — caution"
        sub_lbl = Gtk.Label(
            label=f"{nic.description}  ·  IOMMU group {nic.iommu_group}  "
                  f"·  {nic.pci_address}  ·  {group_status}"
        )
        sub_lbl.set_xalign(0)
        sub_lbl.set_wrap(True)
        sub_lbl.add_css_class("caption")
        sub_lbl.add_css_class("dim-label")
        text.append(sub_lbl)

        inner.append(text)

        # Make entire row clickable to toggle the checkbox
        gesture = Gtk.GestureClick()
        gesture.connect("released", lambda g, n, x, y, c=check: c.set_active(not c.get_active()))
        row.add_controller(gesture)

        row.set_child(inner)
        self._check_buttons[nic.iface] = check

        if check.get_active() and nic not in self.state.selected_nics:
            self.state.selected_nics.append(nic)

        return row

    def _on_toggled(self, check: Gtk.CheckButton, nic: NICDevice):
        if check.get_active():
            if nic not in self.state.selected_nics:
                self.state.selected_nics.append(nic)
        else:
            if nic in self.state.selected_nics:
                self.state.selected_nics.remove(nic)
        self._update_continue()

    def _update_continue(self):
        self._next_btn.set_sensitive(len(self.state.selected_nics) > 0)

    def _on_continue(self):
        self.go_to("gpu")
